// Unit models for the 1917 and 2026 eras, made in Blender (tools/blender/models.py builds them;
// tools/blender/tojs.js writes this file). Each model has one topology and 8 poses (4 marching, 4 fighting),
// stored as base64 int8 vertex positions (scaled per model to fit). Figures.build() asks Models.parts() for these kinds.
'use strict';
const Models = (function () {
  const KEYS = ["cloth","vehicle","dark","metal","skin","canvas","mark","wood","white","gear","glass","rubber","flash","smoke","rocket","gasmask"];
  const DATA = {"gastroops":{"nv":1002,"faces":"","s":11.6097,"frames":["","","","","","","",""]},"mark4":{"nv":261,"faces":"","s":15.875,"frames":["","","","","","","",""]},"renaultft":{"nv":232,"faces":"","s":22.6786,"frames":["","","","","","","",""]},"railgun":{"nv":226,"faces":"","s":9.9975,"frames":["","","","","","","",""]},"modern":{"nv":978,"faces":"","s":11.6097,"frames":["","","","","","","",""]},"militia":{"nv":891,"faces":"","s":11.6716,"frames":["","","","","","","",""]},"mbt":{"nv":430,"faces":"","s":12.2824,"frames":["","","","","","","",""]},"ifv":{"nv":363,"faces":"","s":21.8213,"frames":["","","","","","","",""]},"spg":{"nv":370,"faces":"","s":12.363,"frames":["","","","","","","",""]},"mlrs":{"nv":322,"faces":"","s":9.5978,"frames":["","","","","","","",""]},"sam":{"nv":290,"faces":"","s":7.486,"frames":["","","","","","","",""]},"drone":{"nv":742,"faces":"","s":10.9232,"frames":["","","","","","","",""]},"heli":{"nv":267,"faces":"","s":11.7733,"frames":["","","","","","","",""]}};
  const cache = new Map();
  function b64(s) { const b = atob(s), u = new Uint8Array(b.length); for (let i = 0; i < b.length; i++) u[i] = b.charCodeAt(i); return u.buffer; }
  function decode(kind) {
    let M = cache.get(kind);
    if (M) return M;
    const d = DATA[kind], fl = new Uint16Array(b64(d.faces)), faces = [];
    for (let i = 0; i < fl.length;) { const k = fl[i], n = fl[i + 1]; faces.push([KEYS[k], Array.from(fl.subarray(i + 2, i + 2 + n))]); i += 2 + n; }
    const frames = d.frames.map(s => { const q = new Int8Array(b64(s)), v = new Float32Array(q.length); for (let i = 0; i < q.length; i++) v[i] = q[i] / d.s; return v; });
    M = { faces, frames };
    cache.set(kind, M);
    return M;
  }
  const mix = (a, b, t) => [0, 1, 2].map(i => Math.round(a[i] + (b[i] - a[i]) * t));
  // colours the nation palette lacks
  function colour(P, k) {
    if (P[k]) return P[k];
    switch (k) {
      case 'gear': return mix(P.cloth, P.dark, 0.4);
      case 'glass': return [120, 150, 165];
      case 'rubber': return [34, 34, 32];
      case 'flash': return [255, 226, 130];
      case 'smoke': return [176, 172, 164];
      case 'rocket': return [208, 204, 190];
      case 'gasmask': return [74, 76, 64];
    }
    return [128, 128, 128];
  }
  function has(kind) { return !!DATA[kind]; }
  // the faces of one pose, in the { v: [[x, y, z], ...], c: [r, g, b] } form the figure renderer draws
  function parts(kind, P, f, fighting) {
    const M = decode(kind), fr = M.frames[(fighting ? 4 : 0) + (f % 4)];
    return M.faces.map(([k, idx]) => ({ v: idx.map(i => [fr[i * 3], fr[i * 3 + 1], fr[i * 3 + 2]]), c: colour(P, k), two: k === 'flash' || k === 'smoke' }));
  }
  return { has, parts, kinds: Object.keys(DATA) };
})();
